  3	public final class QuickSort {
  4	    private static final int INSERTION_SORT_THRESHOLD = 16;
  5	
  6	    private QuickSort() {
  7	        // Utility class.
  8	    }
  9	
 10	    public static void sort(int[] values) {
 11	        Objects.requireNonNull(values, "values");
 12	        sort(values, 0, values.length);
 13	    }
 14	
 15	    public static void sort(int[] values, int fromIndex, int toIndexExclusive) {
 16	        Objects.requireNonNull(values, "values");
 17	        checkRange(values.length, fromIndex, toIndexExclusive);
 18	        if (toIndexExclusive - fromIndex < 2) {
 19	            return;
 20	        }
 21	
 22	        quickSort(values, fromIndex, toIndexExclusive - 1);
 23	    }
 24	
 25	    private static void quickSort(int[] values, int left, int right) {
 26	        while (right - left > INSERTION_SORT_THRESHOLD) {
 27	            int pivotIndex = partition(values, left, right);
 28	
 29	            if (pivotIndex - left < right - pivotIndex) {
 30	                quickSort(values, left, pivotIndex - 1);
 31	                left = pivotIndex + 1;
 32	            } else {
 33	                quickSort(values, pivotIndex + 1, right);
 34	                right = pivotIndex - 1;
 35	            }
 36	        }
 37	
 38	        insertionSort(values, left, right);
 39	    }
 40	
 41	    private static int partition(int[] values, int left, int right) {
 42	        int pivotIndex = medianOfThree(values, left, right);
 43	        int pivot = values[pivotIndex];
 44	        swap(values, pivotIndex, right);
 45	
 46	        int storeIndex = left - 1;
 47	
 48	        for (int index = left; index < right; index++) {
 49	            if (values[index] < pivot) {
 50	                storeIndex++;
 51	                swap(values, storeIndex, index);
 52	            }
 53	        }
 54	
 55	        swap(values, storeIndex + 1, right);
 56	        return storeIndex + 1;
 57	    }
 58	
 59	    private static void checkRange(int length, int fromIndex, int toIndexExclusive) {
 60	        if (fromIndex < 0) {
 61	            throw new IndexOutOfBoundsException("fromIndex (" + fromIndex + ") is negative");
 62	        }
 63	        if (toIndexExclusive > length) {
 64	            throw new IndexOutOfBoundsException(
 65	                    "toIndexExclusive (" + toIndexExclusive + ") is greater than array length (" + length + ")");
 66	        }
 67	        if (fromIndex > toIndexExclusive) {
 68	            throw new IllegalArgumentException(
 69	                    "fromIndex (" + fromIndex + ") is greater than toIndexExclusive (" + toIndexExclusive + ")");
 70	        }
 71	    }
 72	
 73	    private static int medianOfThree(int[] values, int left, int right) {
 74	        int middle = left + ((right - left) >>> 1);
 75	
 76	        if (values[left] > values[middle]) {
 77	            swap(values, left, middle);
 78	        }
 79	        if (values[left] > values[right]) {
 80	            swap(values, left, right);
 81	        }
 82	        if (values[middle] > values[right]) {
 83	            swap(values, middle, right);
 84	        }
 85	
 86	        return middle;
 87	    }
 88	
 89	    private static void insertionSort(int[] values, int left, int right) {
 90	        for (int index = left + 1; index <= right; index++) {
 91	            int currentValue = values[index];
 92	            int position = index - 1;
 93	
 94	            while (position >= left && values[position] > currentValue) {
 95	                values[position + 1] = values[position];
 96	                position--;
 97	            }
 98	
 99	            values[position + 1] = currentValue;
100	        }
101	    }
102	
103	    private static void swap(int[] values, int first, int second) {
104	        int temp = values[first];
105	        values[first] = values[second];
106	        values[second] = temp;
107	    }
108	}

